-- Hosbah (MH-575 H3): a team's public status page. slug is a global namespace (like app and proxy
-- host domains) checked by the API, not by this constraint alone, so a taken slug answers 409, not
-- a database error. monitor_ids names the monitors it shows, in order; it is the API's job to keep
-- it a subset of the team's own monitors (a monitor removed from a page is simply dropped from
-- monitor_ids, never blocked by a foreign key, so deleting a monitor never fails). The public
-- endpoint (internal/api's public.go) reads a published page and only its chosen monitors — nothing
-- else about the team. Read/write: any member reads, owner or admin writes.
ALTER TABLE status_pages ADD CONSTRAINT status_pages_slug_check CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$');
ALTER TABLE status_pages ADD CONSTRAINT status_pages_title_check CHECK (length(title) BETWEEN 1 AND 120);
CREATE UNIQUE INDEX status_pages_slug_key ON status_pages (slug);
CREATE UNIQUE INDEX status_pages_team_title_key ON status_pages (team_id, title);
CREATE INDEX status_pages_team_idx ON status_pages (team_id);
